outine"]},{"id":"it-tardi","language_code":"it","unit_id":"it-a2-u11","text":"tardi","translation_es":"tarde","accepted_translations":[],"ipa":null,"romanization":null,"emoji":null,"example_en":"Torno a casa tardi.","example_es":"Vuelvo tarde a casa.","difficulty":1,"tags":["time","routine"]},{"id":"it-spesso","language_code":"it","unit_id":"it-a2-u11","text":"spesso","translation_es":"seguido","accepted_translations":["a menudo","frecuentemente"],"ipa":null,"romanization":null,"emoji":null,"example_en":"Vado spesso al cinema.","example_es":"Voy seguido al cine.","difficulty":1,"tags":["time"]},{"id":"it-qualche-volta","language_code":"it","unit_id":"it-a2-u11","text":"qualche volta","translation_es":"a veces","accepted_translations":["algunas veces"],"ipa":null,"romanization":null,"emoji":null,"example_en":"Qualche volta vado al mare.","example_es":"A veces voy al mar.","difficulty":1,"tags":["time"]},{"id":"it-marito","language_code":"it","unit_id":"it-a2-u11","text":"marito","translation_es":"marido","accepted_translations":["esposo"],"ipa":null,"romanization":null,"emoji":null,"example_en":"Mio marito è medico.","example_es":"Mi marido es médico.","difficulty":1,"tags":["family"]},{"id":"it-moglie","language_code":"it","unit_id":"it-a2-u11","text":"moglie","translation_es":"esposa","accepted_translations":["mujer"],"ipa":null,"romanization":null,"emoji":null,"example_en":"Sua moglie è italiana.","example_es":"Su esposa es italiana.","difficulty":1,"tags":["family"]},{"id":"it-mi-sono-alzato","language_code":"it","unit_id":"it-a2-u11","text":"mi sono alzato","translation_es":"me levanté","accepted_translations":[],"ipa":null,"romanization":null,"emoji":null,"example_en":"Mi sono alzato tardi.","example_es":"Me levanté tarde.","difficulty":1,"tags":["verbs","past","routine"]},{"id":"it-fidanzato","language_code":"it","unit_id":"it-a2-u11","text":"fidanzato","translation_es":"novio","accepted_translations":["novia","prometido","prometida"],"ipa":null,"romanization":null,"emoji":null,"example_en":"Il mio fidanzato si chiama Luca.","example_es":"Mi novio se llama Luca.","difficulty":1,"tags":["family"]},{"id":"it-ci-siamo-conosciuti","language_code":"it","unit_id":"it-a2-u11","text":"ci siamo conosciuti","translation_es":"nos conocimos","accepted_translations":[],"ipa":null,"romanization":null,"emoji":null,"example_en":"Ci siamo conosciuti a una festa.","example_es":"Nos conocimos en una fiesta.","difficulty":1,"tags":["past","family"]},{"id":"it-si-sono-sposati","language_code":"it","unit_id":"it-a2-u11","text":"si sono sposati","translation_es":"se casaron","accepted_translations":[],"ipa":null,"romanization":null,"emoji":null,"example_en":"I miei genitori si sono sposati a Roma.","example_es":"Mis papás se casaron en Roma.","difficulty":1,"tags":["past","family"]},{"id":"it-ci-sentiamo","language_code":"it","unit_id":"it-a2-u11","text":"ci sentiamo","translation_es":"hablamos (más tarde)","accepted_translations":["hablamos","nos hablamos"],"ipa":null,"romanization":null,"emoji":null,"example_en":"Ci sentiamo stasera!","example_es":"¡Hablamos esta noche!","difficulty":1,"tags":["invitations"]},{"id":"it-ci-vado","language_code":"it","unit_id":"it-a2-u11","text":"ci vado","translation_es":"voy (ahí)","accepted_translations":["voy"],"ipa":null,"romanization":null,"emoji":null,"example_en":"Ci vado ogni giorno.","example_es":"Voy todos los días.","difficulty":1,"tags":["pronouns"]},{"id":"it-secondo-me","language_code":"it","unit_id":"it-a2-u12","text":"secondo me","translation_es":"para mí","accepted_translations":["en mi opinión","a mi parecer"],"ipa":null,"romanization":null,"emoji":null,"example_en":"Secondo me è una bella idea.","example_es":"Para mí es una buena idea.","difficulty":1,"tags":["opinions"]},{"id":"it-penso-di-si","language_code":"it","unit_id":"it-a2-u12","text":"penso di sì","translation_es":"creo que sí","accepted_translations":["pienso que sí"],"ipa":null,"romanization":null,"emoji":null,"example_en":"Viene anche Marco? — Penso di sì.","example_es":"¿Viene también Marco? — Creo que sí.","difficulty":1,"tags":["opinions"]},{"id":"it-sono-d-accordo","language_code":"it","unit_id":"it-a2-u12","text":"sono d'accordo","translation_es":"estoy de acuerdo","accepted_translations":[],"ipa":null,"romanization":null,"emoji":null,"example_en":"Sono d'accordo con te.","example_es":"Estoy de acuerdo con vos.","difficulty":1,"tags":["opinions"]},{"id":"it-invece","language_code":"it","unit_id":"it-a2-u12","text":"invece","translation_es":"en cambio","accepted_translations":[],"ipa":null,"romanization":null,"emoji":null,"example_en":"Io prendo un caffè, invece lei prende un tè.","example_es":"Yo tomo un café; ella, en cambio, un té.","difficulty":1,"tags":["connectors"]},{"id":"it-mi-piacerebbe","language_code":"it","unit_id":"it-a2-u12","text":"mi piacerebbe","translation_es":"me gustaría","accepted_translations":[],"ipa":null,"romanization":null,"emoji":null,"example_en":"Mi piacerebbe vivere in Italia.","example_es":"Me gustaría vivir en Italia.","difficulty":1,"tags":["opinions","conditional"]},{"id":"it-preferirei","language_code":"it","unit_id":"it-a2-u12","text":"preferirei","translation_es":"preferiría","accepted_translations":[],"ipa":null,"romanization":null,"emoji":null,"example_en":"Preferirei una città piccola.","example_es":"Preferiría una ciudad chica.","difficulty":1,"tags":["opinions","conditional"]},{"id":"it-sarebbe","language_code":"it","unit_id":"it-a2-u12","text":"sarebbe","translation_es":"sería","accepted_translations":[],"ipa":null,"romanization":null,"emoji":null,"example_en":"Sarebbe meglio partire presto.","example_es":"Sería mejor salir temprano.","difficulty":1,"tags":["conditional"]},{"id":"it-purtroppo","language_code":"it","unit_id":"it-a2-u12","text":"purtroppo","translation_es":"lamentablemente","accepted_translations":["por desgracia"],"ipa":null,"romanization":null,"emoji":null,"example_en":"Purtroppo non posso.","example_es":"Lamentablemente no puedo.","difficulty":1,"tags":["connectors"]},{"id":"it-dovresti","language_code":"it","unit_id":"it-a2-u12","text":"dovresti","translation_es":"deberías","accepted_translations":[],"ipa":null,"romanization":null,"emoji":null,"example_en":"Dovresti riposare.","example_es":"Deberías descansar.","difficulty":1,"tags":["conditional"]},{"id":"it-sensibile","language_code":"it","unit_id":"it-a2-u12","text":"sensibile","translation_es":"sensible","accepted_translations":[],"ipa":null,"romanization":null,"emoji":null,"example_en":"Mia sorella è molto sensibile.","example_es":"Mi hermana es muy sensible.","difficulty":1,"tags":["descriptions"]},{"id":"it-comunque","language_code":"it","unit_id":"it-a2-u12","text":"comunque","translation_es":"de todos modos","accepted_translations":["igual","de todas formas"],"ipa":null,"romanization":null,"emoji":null,"example_en":"Comunque prova!","example_es":"¡De todos modos, probá!","difficulty":1,"tags":["connectors"]},{"id":"it-non-funziona","language_code":"it","unit_id":"it-a2-u12","text":"non funziona","translation_es":"no funciona","accepted_translations":["no anda"],"ipa":null,"romanization":null,"emoji":null,"example_en":"Il cellulare non funziona.","example_es":"El celular no anda.","difficulty":1,"tags":["problems"]},{"id":"it-si-e-rotto","language_code":"it","unit_id":"it-a2-u12","text":"si è rotto","translation_es":"se rompió","accepted_translations":[],"ipa":null,"romanization":null,"emoji":null,"example_en":"Il portatile si è rotto.","example_es":"Se rompió la notebook.","difficulty":1,"tags":["problems","past"]},{"id":"it-problema","language_code":"it","unit_id":"it-a2-u12","text":"problema","translation_es":"problema","accepted_translations":[],"ipa":null,"romanization":null,"emoji":null,"example_en":"Qual è il problema?","example_es":"¿Cuál es el problema?","difficulty":1,"tags":["problems"]},{"id":"it-cambiare","language_code":"it","unit_id":"it-a2-u12","text":"cambiare","translation_es":"cambiar","accepted_translations":[],"ipa":null,"romanization":null,"emoji":null,"example_en":"Vorrei cambiare la giacca.","example_es":"Quisiera cambiar la campera.","difficulty":1,"tags":["problems","shopping"]},{"id":"it-scontrino","language_code":"it","unit_id":"it-a2-u12","text":"scontrino","translation_es":"ticket (de compra)","accepted_translations":["ticket","comprobante"],"ipa":null,"romanization":null,"emoji":"🧾","example_en":"Ha lo scontrino?","example_es":"¿Tiene el ticket?","difficulty":1,"tags":["problems","shopping"]},{"id":"it-rimborso","language_code":"it","unit_id":"it-a2-u12","text":"rimborso","translation_es":"reembolso","accepted_translations":["devolución del dinero"],"ipa":null,"romanization":null,"emoji":null,"example_en":"Vorrei il rimborso.","example_es":"Quisiera el reembolso.","difficulty":1,"tags":["problems","shopping"]}],"lessons":[{"id":"it-a1-u13-l01","unit_id":"it-a1-u13","position":1,"title_es":"Noi, voi, loro","objective_es":"Hablar de varias personas con essere.","intro":{"explanation":"Para hablar de varias personas: noi (nosotros), voi (ustedes) y loro (ellos, ellas). Essere: noi siamo, voi siete, loro sono. Ojo con siete: no es el número 7 (sette), es «ustedes son».","examples":[{"target":"Noi siamo amici.","base":"Somos amigos."},{"target":"Voi siete italiani?","base":"¿Ustedes son italianos?"}]},"takeaways":["Usás noi, voi y loro.","Conjugás essere en plural: siamo, siete, sono."]},{"id":"it-a1-u13-l02","unit_id":"it-a1-u13","position":2,"title_es":"Lavoriamo, lavorano","objective_es":"Conjugar los verbos en -are en plural.","intro":{"explanation":"En plural, los verbos en -are terminan en -iamo (noi), -ate (voi) y -ano (loro): lavoriamo, lavorate, lavorano. En lavorano el acento va atrás: la-vó-ra-no, nunca «lavoranó».","examples":[{"target":"Noi lavoriamo la mattina.","base":"Trabajamos a la mañana."},{"target":"Loro lavorano a casa.","base":"Ellos trabajan en casa."}]},"takeaways":["Conjugás -are en plural: lavoriamo, lavorate, lavorano.","Decís cuándo y dónde trabaja un grupo."]},{"id":"it-a1-u13-rev1","unit_id":"it-a1-u13","position":3,"title_es":"Repaso 1","objective_es":"Consolidar «Noi, voi, loro» y «Lavoriamo, lavorano».","intro":null,"takeaways":[]},{"id":"it-a1-u13-l03","unit_id":"it-a1-u13","position":4,"title_es":"Che lavoro fai?","objective_es":"Preguntar y decir de qué trabaja alguien.","intro":{"explanation":"Che lavoro fai? es «¿de qué trabajás?». Se responde con sono y la profesión sin artículo (sono medico) o con faccio y artículo (faccio il cuoco). En femenino, -o pasa a -a (cuoca) y -iere a -iera (infermiera); insegnante no cambia.","examples":[{"target":"Che lavoro fai? — Sono infermiera.","base":"¿De qué trabajás? — Soy enfermera."},{"target":"Faccio il cuoco.","base":"Soy cocinero."}]},"takeaways":["Preguntás la profesión con che lavoro fai?","Decís profesiones con sono o con faccio il / la."]},{"id":"it-a1-u13-l04","unit_id":"it-a1-u13","position":5,"title_es":"In ufficio, in negozio","objective_es":"Decir dónde trabaja cada uno.","intro":{"explanation":"Se dice lavoro in ufficio, in negozio, in ospedale (sin artículo). Ojo: negozio es la tienda, el local; el cameriere (el mozo) no tiene nada que ver con la camera (la habitación).","examples":[{"target":"Lavoro in ufficio.","base":"Trabajo en una oficina."},{"target":"Mio fratello è commesso in un negozio.","base":"Mi hermano es vendedor en una tienda."}]},"takeaways":["Decís dónde trabajás: in ufficio, in negozio.","Nombrás trabajos de la tienda y del restaurante."]},{"id":"it-a1-u13-rev2","unit_id":"it-a1-u13","position":6,"title_es":"Repaso 2","objective_es":"Consolidar «Che lavoro fai?» y «In ufficio, in negozio».","intro":null,"takeaways":[]},{"id":"it-a1-u13-l05","unit_id":"it-a1-u13","position":7,"title_es":"Il nostro lavoro","objective_es":"Usar nostro y nostra y entender la presentación de un grupo.","intro":{"explanation":"Nostro y nostra son «nuestro» y «nuestra». En italiano llevan artículo: il nostro ristorante, la nostra casa. Concuerdan con la cosa, no con las personas que hablan.","examples":[{"target":"Il nostro ufficio è piccolo.","base":"Nuestra oficina es chica."},{"target":"La nostra famiglia è grande.","base":"Nuestra familia es grande."}]},"takeaways":["Usás il nostro y la nostra según la cosa.","Entendés una presentación de un grupo."]},{"id":"it-a1-u13-listen","unit_id":"it-a1-u13","position":8,"title_es":"Práctica de escucha","objective_es":"Reconocer de oído las palabras y frases de la unidad.","intro":null,"takeaways":[]},{"id":"it-a1-u13-words","unit_id":"it-a1-u13","position":9,"title_es":"Palabras de la unidad","objective_es":"Fijar el vocabulario de la unidad: reconocerlo y escribirlo.","intro":null,"takeaways":[]},{"id":"it-a1-u13-final","unit_id":"it-a1-u13","position":10,"title_es":"Repaso final","objective_es":"Demostrar todo lo de «Profesiones y trabajo».","intro":null,"takeaways":[]},{"id":"it-a1-u14-l01","unit_id":"it-a1-u14","position":1,"title_es":"Sono stanco","objective_es":"Decir cómo estás con essere y con stare.","intro":{"explanation":"En italiano los estados van con essere: sono stanco es «estoy cansado» y sono felice, «estoy feliz». Stare se usa sobre todo para la salud y el saludo: sto bene, sto male. Por eso: come stai? — Sto male, sono malato.","examples":[{"target":"Oggi sono stanca.","base":"Hoy estoy cansada."},{"target":"Sto male, sono malato.","base":"Me siento mal, estoy enfermo."}]},"takeaways":["Decís cómo estás con sono: stanco, felice, malato.","Decís cómo te sentís con sto bene / sto male."]},{"id":"it-a1-u14-l02","unit_id":"it-a1-u14","position":2,"title_es":"Ho fame, ho sete","objective_es":"Decir si tenés hambre, sed, frío o calor.","intro":{"explanation":"Hambre, sed, frío y calor van con avere, como en español: ho fame, ho sete, ho freddo, ho caldo. Ojo: caldo no es el caldo de la sopa, es «calor» o «caliente»: ho caldo es «tengo calor».","examples":[{"target":"Ho fame e ho sete.","base":"Tengo hambre y tengo sed."},{"target":"Ho caldo, vorrei un gelato.","base":"Tengo calor, quisiera un helado."}]},"takeaways":["Decís ho fame, ho sete, ho freddo y ho caldo.","Sabés que caldo es «calor»."]},{"id":"it-a1-u14-rev1","unit_id":"it-a1-u14","position":3,"title_es":"Repaso 1","objective_es":"Consolidar «Sono stanco» y «Ho fame, ho sete».","intro":null,"takeaways":[]},{"id":"it-a1-u14-l03","unit_id":"it-a1-u14","position":4,"title_es":"Com'è?","objective_es":"Describir cómo es una persona.","intro":{"explanation":"Com'è? es «¿cómo es?». Se responde con è: è alto, è bassa, è giovane. El pelo y los ojos van con avere y artículo: ha i capelli neri, ha gli occhi blu. El adjetivo concuerda: capelli lunghi, sorella bassa.","examples":[{"target":"Com'è tuo fratello? — È alto.","base":"¿Cómo es tu hermano? — Es alto."},{"target":"Ha i capelli lunghi.","base":"Tiene el pelo largo."}]},"takeaways":["Preguntás com'è? y describís con è y ha.","Hacés concordar el adjetivo: basso, bassa, bassi."]},{"id":"it-a1-u14-l04","unit_id":"it-a1-u14","position":5,"title_es":"Simpatico, ma un po' timido","objective_es":"Describir el carácter y matizar con un po’ y ma.","intro":{"explanation":"Para el carácter: simpatico (buena onda) y carino (lindo, amable). Ojo: carino no es «cariño». Un po' es «un poco» y ma es «pero»: è carina ma un po' timida.","examples":[{"target":"Il mio amico è simpatico.","base":"Mi amigo es simpático."},{"target":"È carina ma un po' timida.","base":"Es linda pero un poco tímida."}]},"takeaways":["Describís el carácter con simpatico y carino.","Matizás con un po' y ma."]},{"id":"it-a1-u14-rev2","unit_id":"it-a1-u14","position":6,"title_es":"Repaso 2","objective_es":"Consolidar «Com'è?» y «Simpatico, ma un po' timido».","intro":null,"takeaways":[]},{"id":"it-a1-u14-l05","unit_id":"it-a1-u14","position":7,"title_es":"Essere, stare, avere","objective_es":"Elegir el verbo justo para decir cómo estás y cómo sos.","intro":{"explanation":"Tres verbos donde el español dice «estar» o «tener»: essere para cómo sos y cómo estás (è alta, sono stanco), stare para la salud (sto male) y avere para hambre, sed, frío y calor (ho freddo).","examples":[{"target":"Paolo è malato e ha freddo.","base":"Paolo está enfermo y tiene frío."},{"target":"Sto bene, ma sono un po' stanca.","base":"Estoy bien, pero un poco cansada."}]},"takeaways":["Elegís entre essere, stare y avere.","Entendés una llamada sobre cómo está alguien."]},{"id":"it-a1-u14-listen","unit_id":"it-a1-u14","position":8,"title_es":"Práctica de escucha","objective_es":"Reconocer de oído las palabras y frases de la unidad.","intro":null,"takeaways":[]},{"id":"it-a1-u14-words","unit_id":"it-a1-u14","position":9,"title_es":"Palabras de la unidad","objective_es":"Fijar el vocabulario de la unidad: reconocerlo y escribirlo.","intro":null,"takeaways":[]},{"id":"it-a1-u14-final","unit_id":"it-a1-u14","position":10,"title_es":"Repaso final","objective_es":"Demostrar todo lo de «¿Cómo sos? ¿Cómo estás?».","intro":null,"takeaways":[]},{"id":"it-a1-u15-l01","unit_id":"it-a1-u15","position":1,"title_es":"Trenta, cinquanta, cento","objective_es":"Contar de diez en diez hasta cien.","intro":{"explanation":"Las decenas: venti, trenta, quaranta, cinquanta… ottanta, cento. Con uno y otto la decena pierde la última vocal: ventuno, trentotto. Cien es cento, sin cambios: cento euro.","examples":[{"target":"Mio padre ha cinquanta anni.","base":"Mi papá tiene cincuenta años."},{"target":"Il biglietto costa cento euro.","base":"El boleto cuesta cien euros."}]},"takeaways":["Contás de diez en diez hasta cento.","Decís edades y precios más grandes."]},{"id":"it-a1-u15-l02","unit_id":"it-a1-u15","position":2,"title_es":"Il primo maggio","objective_es":"Decir la fecha y cuándo es tu cumpleaños.","intro":{"explanation":"Los meses van en minúscula: gennaio, maggio, luglio, agosto, dicembre. La fecha es il + número + mes: il 12 luglio. El día 1 usa el ordinal: il primo maggio. «En julio» es a luglio o in luglio.","examples":[{"target":"Il mio compleanno è il primo maggio.","base":"Mi cumpleaños es el 1 de mayo."},{"target":"Il mio compleanno è a luglio.","base":"Mi cumpleaños es en julio."}]},"takeaways":["Decís la fecha con il + número + mes (il primo para el 1).","Decís en qué mes es algo: a luglio, in luglio."]},{"id":"it-a1-u15-rev1","unit_id":"it-a1-u15","position":3,"title_es":"Repaso 1","objective_es":"Consolidar «Trenta, cinquanta, cento» y «Il primo maggio».","intro":null,"takeaways":[]},{"id":"it-a1-u15-l03","unit_id":"it-a1-u15","position":4,"title_es":"Che tempo fa?","objective_es":"Preguntar y decir qué tiempo hace.","intro":{"explanation":"Che tempo fa? es «¿qué tiempo hace?». Con fare: fa caldo, fa freddo. Sin fare: piove (llueve), nevica (nieva), c’è il sole (hay sol). Ojo: fa caldo es «hace calor», no tiene que ver con el caldo.","examples":[{"target":"Che tempo fa? — Fa caldo.","base":"¿Qué tiempo hace? — Hace calor."},{"target":"Oggi piove e fa freddo.","base":"Hoy llueve y hace frío."}]},"takeaways":["Preguntás che tempo fa?","Decís fa caldo, fa freddo, piove, nevica y c’è il sole."]},{"id":"it-a1-u15-l04","unit_id":"it-a1-u15","position":5,"title_es":"L'estate e l'inverno","objective_es":"Hablar de las estaciones y del clima en cada una.","intro":{"explanation":"Las estaciones: la primavera, l'estate (el verano, femenino), l'autunno y l'inverno. «En verano» es d'estate o in estate. Y recordá: en la Argentina diciembre es verano; en Italia, invierno.","examples":[{"target":"D'estate fa caldo.","base":"En verano hace calor."},{"target":"A dicembre in Italia è inverno.","base":"En diciembre en Italia es invierno."}]},"takeaways":["Nombrás l'estate y l'inverno.","Comparás el clima de los dos hemisferios."]},{"id":"it-a1-u15-rev2","unit_id":"it-a1-u15","position":6,"title_es":"Repaso 2","objective_es":"Consolidar «Che tempo fa?» y «L'estate e l'inverno».","intro":null,"takeaways":[]},{"id":"it-a1-u15-l05","unit_id":"it-a1-u15","position":7,"title_es":"Ferragosto","objective_es":"Entender fechas y avisos de días especiales en Italia.","intro":{"explanation":"Fechas que vas a ver en Italia: il primo maggio, Ferragosto (il 15 agosto, en pleno verano) y Natale (il 25 dicembre). Esos días muchos negocios están cerrados: chiuso.","examples":[{"target":"Il 15 agosto è Ferragosto.","base":"El 15 de agosto es Ferragosto."},{"target":"Il primo maggio è festa.","base":"El 1 de mayo es feriado."}]},"takeaways":["Entendés un aviso de cierre por un feriado.","Decís fechas especiales del año."]},{"id":"it-a1-u15-listen","unit_id":"it-a1-u15","position":8,"title_es":"Práctica de escucha","objective_es":"Reconocer de oído las palabras y frases de la unidad.","intro":null,"takeaways":[]},{"id":"it-a1-u15-words","unit_id":"it-a1-u15","position":9,"title_es":"Palabras de la unidad","objective_es":"Fijar el vocabulario de la unidad: reconocerlo y escribirlo.","intro":null,"takeaways":[]},{"id":"it-a1-u15-final","unit_id":"it-a1-u15","position":10,"title_es":"Repaso final","objective_es":"Demostrar todo lo de «Fechas, meses y clima».","intro":null,"takeaways":[]},{"id":"it-a1-u16-l01","unit_id":"it-a1-u16","position":1,"title_es":"In treno, a piedi","objective_es":"Decir cómo vas a los lugares.","intro":{"explanation":"El transporte va con in y sin artículo: in treno, in autobus, in macchina, in bicicletta; caminando es a piedi. Ojo: macchina es el auto (no una máquina). «Tomar» el colectivo es prendere: prendo l’autobus.","examples":[{"target":"Vado a scuola a piedi.","base":"Voy a la escuela a pie."},{"target":"Prendo l’autobus ogni giorno.","base":"Tomo el colectivo todos los días."}]},"takeaways":["Decís cómo vas: in treno, in macchina, a piedi.","Sabés que macchina es «auto»."]},{"id":"it-a1-u16-l02","unit_id":"it-a1-u16","position":2,"title_es":"Al mare, alla stazione","objective_es":"Decir adónde vas con al y alla.","intro":{"explanation":"A + il = al y a + la = alla: vado al cinema, al mare, alla stazione. Con la montaña se usa in: vado in montagna. Andiamo es «vamos»: andiamo al mare!","examples":[{"target":"Sabato vado al mare.","base":"El sábado voy al mar."},{"target":"Andiamo alla stazione.","base":"Vamos a la estación."}]},"takeaways":["Usás al y alla para decir adónde vas.","Decís in montagna y al mare."]},{"id":"it-a1-u16-rev1","unit_id":"it-a1-u16","position":3,"title_es":"Repaso 1","objective_es":"Consolidar «In treno, a piedi» y «Al mare, alla stazione».","intro":null,"takeaways":[]},{"id":"it-a1-u16-l03","unit_id":"it-a1-u16","position":4,"title_es":"Andiamo, andate, vanno","objective_es":"Conjugar andare en plural y entender cómo viaja un grupo.","intro":{"explanation":"Andare es irregular: vado, vai, va, andiamo, andate, vanno. Con noi y voi vuelve la raíz and-: andiamo, andate. Con loro: vanno.","examples":[{"target":"I miei genitori vanno in montagna.","base":"Mis papás van a la montaña."},{"target":"Voi andate al mare?","base":"¿Ustedes van al mar?"}]},"takeaways":["Conjugás andare: andiamo, andate, vanno.","Entendés cómo viaja un grupo."]},{"id":"it-a1-u16-l04","unit_id":"it-a1-u16","position":5,"title_es":"Ieri ho mangiato…","objective_es":"Contar en pocas palabras qué hiciste ayer.","intro":{"explanation":"Para contar lo que hiciste se usa avere + participio: ho mangiato (comí), ho visto (vi). Ieri es «ayer». Para preguntar: cosa hai fatto? (¿qué hiciste?). En la U1 del A2 lo vas a ver completo.","examples":[{"target":"Ieri ho mangiato una pizza.","base":"Ayer comí una pizza."},{"target":"Cosa hai fatto ieri?","base":"¿Qué hiciste ayer?"}]},"takeaways":["Preguntás cosa hai fatto?","Contás algo de ayer con ho mangiato y ho visto."]},{"id":"it-a1-u16-rev2","unit_id":"it-a1-u16","position":6,"title_es":"Repaso 2","objective_es":"Consolidar «Andiamo, andate, vanno» y «Ieri ho mangiato…».","intro":null,"takeaways":[]},{"id":"it-a1-u16-l05","unit_id":"it-a1-u16","position":7,"title_es":"Sono andato al cinema","objective_es":"Contar adónde fuiste y entender planes de fin de semana.","intro":{"explanation":"Con andare el pasado va con essere, y el participio concuerda con quien habla: sono andato (varón), sono andata (mujer). Y ojo: guardare es «mirar», no «guardar»: guardo la TV, ho guardato un film.","examples":[{"target":"Ieri sono andata al mare.","base":"Ayer fui al mar."},{"target":"Mi piace guardare la TV.","base":"Me gusta mirar la tele."}]},"takeaways":["Decís adónde fuiste: sono andato / sono andata.","Sabés que guardare es «mirar»."]},{"id":"it-a1-u16-listen","unit_id":"it-a1-u16","position":8,"title_es":"Práctica de escucha","objective_es":"Reconocer de oído las palabras y frases de la unidad.","intro":null,"takeaways":[]},{"id":"it-a1-u16-words","unit_id":"it-a1-u16","position":9,"title_es":"Palabras de la unidad","objective_es":"Fijar el vocabulario de la unidad: reconocerlo y escribirlo.","intro":null,"takeaways":[]},{"id":"it-a1-u16-final","unit_id":"it-a1-u16","position":10,"title_es":"Repaso final","objective_es":"Demostrar todo lo de «Transporte, tiempo libre y ayer».","intro":null,"takeaways":[]},{"id":"it-a2-u01-l01","unit_id":"it-a2-u01","position":1,"title_es":"Ho parlato, ho dormito","objective_es":"Contar lo que hiciste con los participios regulares.","intro":{"explanation":"El passato prossimo cuenta algo terminado: avere + participio. -are → -ato (parlato), -ere → -uto (bevuto), -ire → -ito (dormito). Donde decimos «hablé», en italiano se dice ho parlato.","examples":[{"target":"Ieri ho parlato con mia madre.","base":"Ayer hablé con mi mamá."},{"target":"Ho dormito molto.","base":"Dormí mucho."}]},"takeaways":["Formás el passato prossimo con ho + participio.","Conocés los participios en -ato, -uto, -ito."]},{"id":"it-a2-u01-l02","unit_id":"it-a2-u01","position":2,"title_es":"Ho fatto, ho preso","objective_es":"Usar los participios irregulares más frecuentes.","intro":{"explanation":"Algunos participios son irregulares: fare → fatto, leggere → letto, scrivere → scritto, prendere → preso (y vedere → visto). Ojo: fare la spesa es hacer las compras de comida, y la lettera es la carta que se escribe.","examples":[{"target":"Ho fatto la spesa al supermercato.","base":"Hice las compras en el súper."},{"target":"Ho preso il treno alle otto.","base":"Tomé el tren a las ocho."}]},"takeaways":["Usás fatto, letto, scritto y preso.","Decís que hiciste las compras: ho fatto la spesa."]},{"id":"it-a2-u01-rev1","unit_id":"it-a2-u01","position":3,"title_es":"Repaso 1","objective_es":"Consolidar «Ho parlato, ho dormito» y «Ho fatto, ho preso».","intro":null,"takeaways":[]},{"id":"it-a2-u01-l03","unit_id":"it-a2-u01","position":4,"title_es":"Abbiamo mangiato, hanno parlato","objective_es":"Contar lo que hizo un grupo.","intro":{"explanation":"Avere en plural: abbiamo (noi), avete (voi), hanno (loro). Con avere el participio no cambia aunque hablen varias personas: abbiamo mangiato, hanno parlato, Sara ha letto.","examples":[{"target":"Abbiamo mangiato in una trattoria.","base":"Comimos en una trattoria."},{"target":"I miei amici hanno parlato tutto il giorno.","base":"Mis amigos hablaron todo el día."}]},"takeaways":["Contás en plural: abbiamo, hanno + participio.","Sabés que con avere el participio no concuerda."]},{"id":"it-a2-u01-l04","unit_id":"it-a2-u01","position":5,"title_es":"Già, non… ancora","objective_es":"Decir lo que ya hiciste y lo que todavía no.","intro":{"explanation":"Già (ya) y ancora (todavía) van entre avere y el participio: ho già mangiato (ya comí), non ho ancora mangiato (todavía no comí). Non… ancora también sirve solo: non ancora!","examples":[{"target":"Ho già fatto la spesa.","base":"Ya hice las compras."},{"target":"Non ho ancora scritto alla nonna.","base":"Todavía no le escribí a la abuela."}]},"takeaways":["Decís ho già + participio.","Decís non ho ancora + participio."]},{"id":"it-a2-u01-rev2","unit_id":"it-a2-u01","position":6,"title_es":"Repaso 2","objective_es":"Consolidar «Abbiamo mangiato, hanno parlato» y «Già, non… ancora».","intro":null,"takeaways":[]},{"id":"it-a2-u01-l05","unit_id":"it-a2-u01","position":7,"title_es":"Sabato scorso","objective_es":"Ubicar en el tiempo lo que hiciste y entender un relato.","intro":{"explanation":"Para el pasado: stamattina (esta mañana), ieri sera (anoche), sabato scorso, la settimana scorsa (scorso concuerda). Ojo: la partita es el partido; la partida de un viaje es otra cosa.","examples":[{"target":"Ieri sera ho visto la partita.","base":"Anoche vi el partido."},{"target":"La settimana scorsa ho pulito la casa.","base":"La semana pasada limpié la casa."}]},"takeaways":["Decís cuándo: stamattina, ieri sera, sabato scorso.","Entendés un relato de fin de semana."]},{"id":"it-a2-u01-listen","unit_id":"it-a2-u01","position":8,"title_es":"Práctica de escucha","objective_es":"Reconocer de oído las palabras y frases de la unidad.","intro":null,"takeaways":[]},{"id":"it-a2-u01-words","unit_id":"it-a2-u01","position":9,"title_es":"Palabras de la unidad","objective_es":"Fijar el vocabulario de la unidad: reconocerlo y escribirlo.","intro":null,"takeaways":[]},{"id":"it-a2-u01-final","unit_id":"it-a2-u01","position":10,"title_es":"Repaso final","objective_es":"Demostrar todo lo de «¿Qué hiciste el fin de semana?».","intro":null,"takeaways":[]},{"id":"it-a2-u02-l01","unit_id":"it-a2-u02","position":1,"title_es":"Sono partito, sono arrivato","objective_es":"Contar salidas y llegadas con essere.","intro":{"explanation":"Con los verbos de movimiento (andare, partire, arrivare, tornare) el passato prossimo va con essere, y el participio concuerda como un adjetivo: sono arrivato (él), sono arrivata (ella), siamo arrivati.","examples":[{"target":"Sono arrivata a Roma ieri.","base":"Llegué a Roma ayer."},{"target":"Siamo andati a Napoli in treno.","base":"Fuimos a Nápoles en tren."}]},"takeaways":["Usás essere con partire, arrivare, tornare y andare.","Hacés concordar el participio: arrivato, arrivata, arrivati."]},{"id":"it-a2-u02-l02","unit_id":"it-a2-u02","position":2,"title_es":"Il viaggio, l'aeroporto","objective_es":"Usar el vocabulario del viaje y entender anuncios del aeropuerto.","intro":{"explanation":"Para viajar: il viaggio, la valigia (la valija), l’aereo, l’aeroporto y il volo (el vuelo). En los anuncios vas a oír parte (sale) y in ritardo (demorado).","examples":[{"target":"Il volo parte alle undici.","base":"El vuelo sale a las once."},{"target":"La mia valigia è rossa.","base":"Mi valija es roja."}]},"takeaways":["Nombrás el aereo, la valigia y il volo.","Entendés un anuncio de salida o de demora."]},{"id":"it-a2-u02-rev1","unit_id":"it-a2-u02","position":3,"title_es":"Repaso 1","objective_es":"Consolidar «Sono partito, sono arrivato» y «Il viaggio, l'aeroporto».","intro":null,"takeaways":[]},{"id":"it-a2-u02-l03","unit_id":"it-a2-u02","position":4,"title_es":"Sono stato, sono rimasto","objective_es":"Decir dónde estuviste y cuánto te quedaste.","intro":{"explanation":"Essere y stare comparten participio: sono stato es «estuve» o «fui» (sono stato a Firenze). Rimanere (quedarse) da rimasto: sono rimasto a casa. Los dos van con essere.","examples":[{"target":"Siamo stati in vacanza in Sicilia.","base":"Estuvimos de vacaciones en Sicilia."},{"target":"Domenica sono rimasta a casa.","base":"El domingo me quedé en casa."}]},"takeaways":["Decís dónde estuviste: sono stato / stata.","Decís que te quedaste: sono rimasto / rimasta."]},{"id":"it-a2-u02-l04","unit_id":"it-a2-u02","position":5,"title_es":"Salire, scendere, uscire","objective_es":"No confundir salire con «salir».","intro":{"explanation":"Ojo con el falso amigo: salire es «subir» (sono salito sul treno) y scendere es «bajar» (sono sceso dall’autobus). «Salir» es uscire: sono uscito con gli amici. Todos van con essere.","examples":[{"target":"Sono salito sul treno a Milano.","base":"Subí al tren en Milán."},{"target":"Ieri sera sono uscita con Sara.","base":"Anoche salí con Sara."}]},"takeaways":["Sabés que salire es «subir».","Decís «salí» con sono uscito / uscita."]},{"id":"it-a2-u02-rev2","unit_id":"it-a2-u02","position":6,"title_es":"Repaso 2","objective_es":"Consolidar «Sono stato, sono rimasto» y «Salire, scendere, uscire».","intro":null,"takeaways":[]},{"id":"it-a2-u02-l05","unit_id":"it-a2-u02","position":7,"title_es":"Dieci anni fa","objective_es":"Decir hace cuánto pasó algo y entender el relato de un viaje.","intro":{"explanation":"Fa, después de una cantidad de tiempo, es «hace»: due anni fa (hace dos años), una settimana fa (hace una semana). Va al final: sono arrivato tre giorni fa.","examples":[{"target":"Sono andato in Italia dieci anni fa.","base":"Fui a Italia hace diez años."},{"target":"Siamo partiti due giorni fa.","base":"Partimos hace dos días."}]},"takeaways":["Decís hace cuánto con … fa.","Entendés un relato de viaje en pasado."]},{"id":"it-a2-u02-listen","unit_id":"it-a2-u02","position":8,"title_es":"Práctica de escucha","objective_es":"Reconocer de oído las palabras y frases de la unidad.","intro":null,"takeaways":[]},{"id":"it-a2-u02-words","unit_id":"it-a2-u02","position":9,"title_es":"Palabras de la unidad","objective_es":"Fijar el vocabulario de la unidad: reconocerlo y escribirlo.","intro":null,"takeaways":[]},{"id":"it-a2-u02-final","unit_id":"it-a2-u02","position":10,"title_es":"Repaso final","objective_es":"Demostrar todo lo de «Viajes».","intro":null,"takeaways":[]},{"id":"it-a2-u03-l01","unit_id":"it-a2-u03","position":1,"title_es":"Vorrei prenotare","objective_es":"Reservar una habitación o una mesa.","intro":{"explanation":"Prenotare es «reservar»: vorrei prenotare una camera doppia (doble) o singola (simple). Si algo está incluido, es compreso y concuerda: la colazione è compresa.","examples":[{"target":"Vorrei prenotare una camera doppia.","base":"Quisiera reservar una habitación doble."},{"target":"La colazione è compresa?","base":"¿El desayuno está incluido?"}]},"takeaways":["Reservás con vorrei prenotare…","Preguntás qué está compreso."]},{"id":"it-a2-u03-l02","unit_id":"it-a2-u03","position":2,"title_es":"Il primo, il secondo","objective_es":"Entender el orden del menú italiano.","intro":{"explanation":"El menú italiano va en orden: antipasto, primo (pasta o risotto), secondo (carne o pescado), contorno (la guarnición, que se pide aparte) y dolce (el postre). Muchos comen sólo un primo o un secondo.","examples":[{"target":"Per secondo prendo il pollo.","base":"De segundo pido el pollo."},{"target":"Come contorno, patate.","base":"De guarnición, papas."}]},"takeaways":["Leés un menú: primi, secondi, contorni, dolci.","Pedís un plato de cada parte."]},{"id":"it-a2-u03-rev1","unit_id":"it-a2-u03","position":3,"title_es":"Repaso 1","objective_es":"Consolidar «Vorrei prenotare» y «Il primo, il secondo».","intro":null,"takeaways":[]},{"id":"it-a2-u03-l03","unit_id":"it-a2-u03","position":4,"title_es":"Mi porta…? Potrei…?","objective_es":"Pedir con cortesía tratando de usted.","intro":{"explanation":"Al mozo se le habla de Lei (usted), con el verbo en tercera persona: mi porta il conto? (¿me trae la cuenta?). Para pedir con cortesía: potrei avere…? o posso avere…? Y ojo: il burro es la manteca; el burro, el animal, es l’asino.","examples":[{"target":"Mi porta il conto, per favore?","base":"¿Me trae la cuenta, por favor?"},{"target":"Potrei avere un’acqua?","base":"¿Podría tomar un agua?"}]},"takeaways":["Pedís con mi porta…?, potrei avere…? y posso avere…?","Sabés que burro es «manteca»."]},{"id":"it-a2-u03-l04","unit_id":"it-a2-u03","position":5,"title_es":"Il coperto e la mancia","objective_es":"Entender la cuenta y pagar.","intro":{"explanation":"En la cuenta italiana suele aparecer il coperto, un cargo fijo por persona (como el cubierto en la Argentina). La mancia (propina) no es obligatoria. Se paga in contanti (en efectivo) o con la carta (con tarjeta).","examples":[{"target":"Il coperto costa due euro.","base":"El cubierto cuesta dos euros."},{"target":"Posso pagare con la carta?","base":"¿Puedo pagar con tarjeta?"}]},"takeaways":["Entendés il coperto y la mancia.","Decís cómo pagás: in contanti, con la carta."]},{"id":"it-a2-u03-rev2","unit_id":"it-a2-u03","position":6,"title_es":"Repaso 2","objective_es":"Consolidar «Mi porta…? Potrei…?» y «Il coperto e la mancia».","intro":null,"takeaways":[]},{"id":"it-a2-u03-l05","unit_id":"it-a2-u03","position":7,"title_es":"In albergo e al ristorante","objective_es":"Resolver una reserva y una comida de principio a fin.","intro":{"explanation":"Repasá todo el recorrido: reservar (ho prenotato un tavolo), pedir (per me un primo, mi porta…?), y pagar (il conto, con la carta). En el hotel: una camera singola o doppia, con la colazione compresa.","examples":[{"target":"Ho prenotato un tavolo per due.","base":"Reservé una mesa para dos."},{"target":"Vorrei una camera singola, per favore.","base":"Quisiera una habitación simple, por favor."}]},"takeaways":["Hacés una reserva completa.","Entendés una reseña de un restaurante."]},{"id":"it-a2-u03-listen","unit_id":"it-a2-u03","position":8,"title_es":"Práctica de escucha","objective_es":"Reconocer de oído las palabras y frases de la unidad.","intro":null,"takeaways":[]},{"id":"it-a2-u03-words","unit_id":"it-a2-u03","position":9,"title_es":"Palabras de la unidad","objective_es":"Fijar el vocabulario de la unidad: reconocerlo y escribirlo.","intro":null,"takeaways":[]},{"id":"it-a2-u03-final","unit_id":"it-a2-u03","position":10,"title_es":"Repaso final","objective_es":"Demostrar todo lo de «Restaurantes y hotel».","intro":null,"takeaways":[]},{"id":"it-a2-u04-l01","unit_id":"it-a2-u04","position":1,"title_es":"Ero, era, eravamo","objective_es":"Decir cómo eras con el imperfetto de essere.","intro":{"explanation":"Para describir cómo eran las cosas se usa el imperfetto, como nuestro pretérito imperfecto. Essere: ero (yo era), eri, era (él / ella era), eravamo (éramos). Da piccolo / da piccola es «de chico / de chica».","examples":[{"target":"Da piccola ero molto timida.","base":"De chica era muy tímida."},{"target":"Eravamo sette fratelli.","base":"Éramos siete hermanos."}]},"takeaways":["Usás ero, era y eravamo.","Decís da piccolo / da piccola."]},{"id":"it-a2-u04-l02","unit_id":"it-a2-u04","position":2,"title_es":"Abitavo, giocavo, andavo","objective_es":"Contar lo que hacías siempre.","intro":{"explanation":"Los verbos en -are hacen el imperfetto en -avo: abitavo (vivía), giocavo (jugaba), andavo (iba). Sirve para lo que hacías siempre, a menudo con di solito (por lo general). Ojo: giocare a calcio va sin artículo.","examples":[{"target":"Di solito andavo a scuola a piedi.","base":"Por lo general iba a la escuela a pie."},{"target":"Giocavo a calcio con mio fratello.","base":"Jugaba al fútbol con mi hermano."}]},"takeaways":["Contás hábitos con -avo: abitavo, giocavo, andavo.","Decís di solito y giocare a calcio."]},{"id":"it-a2-u04-rev1","unit_id":"it-a2-u04","position":3,"title_es":"Repaso 1","objective_es":"Consolidar «Ero, era, eravamo» y «Abitavo, giocavo, andavo».","intro":null,"takeaways":[]},{"id":"it-a2-u04-l03","unit_id":"it-a2-u04","position":4,"title_es":"Avevo, facevo, c'era","objective_es":"Decir qué tenías, qué hacías y qué había.","intro":{"explanation":"Avere es regular: avevo (tenía), aveva. Fare usa la raíz fac-: facevo (hacía). Para lo que había: c’era (una cosa) y c’erano (varias). Y lo que te gustaba: mi piaceva.","examples":[{"target":"Da piccolo io avevo un gatto nero.","base":"De chico yo tenía un gato negro."},{"target":"Mi piaceva molto la scuola.","base":"Me gustaba mucho la escuela."}]},"takeaways":["Usás avevo, facevo y c'era.","Decís lo que te gustaba con mi piaceva."]},{"id":"it-a2-u04-l04","unit_id":"it-a2-u04","position":5,"title_es":"Il paese e la campagna","objective_es":"Hablar del lugar donde vivías y entender un recuerdo largo.","intro":{"explanation":"Paese es «país», pero también «pueblo»: abitavo in un piccolo paese. Ojo: la campagna es el campo (no una campaña). Vivir en el campo: abitare in campagna.","examples":[{"target":"Abitavo in un piccolo paese.","base":"Vivía en un pueblo chico."},{"target":"Mio nonno aveva una casa in campagna.","base":"Mi abuelo tenía una casa en el campo."}]},"takeaways":["Sabés que campagna es «campo» y paese, «pueblo».","Entendés a alguien mayor que cuenta su infancia."]},{"id":"it-a2-u04-rev2","unit_id":"it-a2-u04","position":6,"title_es":"Repaso 2","objective_es":"Consolidar «Avevo, facevo, c'era» y «Il paese e la campagna».","intro":null,"takeaways":[]},{"id":"it-a2-u04-l05","unit_id":"it-a2-u04","position":7,"title_es":"Quando ero piccolo…","objective_es":"Contar un recuerdo de tu infancia.","intro":{"explanation":"Para contar recuerdos combinás todo: quando ero piccolo (cuando era chico) + lo que hacías (andavo, giocavo, facevo) + lo que había (c’era) + lo que te gustaba (mi piaceva).","examples":[{"target":"Quando ero piccola, abitavo a Roma.","base":"Cuando era chica, vivía en Roma."},{"target":"Di solito facevo i compiti in cucina.","base":"Por lo general hacía los deberes en la cocina."}]},"takeaways":["Contás un recuerdo con el imperfetto.","Combinás quando ero piccolo, di solito y mi piaceva."]},{"id":"it-a2-u04-listen","unit_id":"it-a2-u04","position":8,"title_es":"Práctica de escucha","objective_es":"Reconocer de oído las palabras y frases de la unidad.","intro":null,"takeaways":[]},{"id":"it-a2-u04-words","unit_id":"it-a2-u04","position":9,"title_es":"Palabras de la unidad","objective_es":"Fijar el vocabulario de la unidad: reconocerlo y escribirlo.","intro":null,"takeaways":[]},{"id":"it-a2-u04-final","unit_id":"it-a2-u04","position":10,"title_es":"Repaso final","objective_es":"Demostrar todo lo de «Cuando era chico».","intro":null,"takeaways":[]},{"id":"it-a2-u05-l01","unit_id":"it-a2-u05","position":1,"title_es":"Cos'è successo?","objective_es":"Preguntar qué pasó y contar que perdiste o encontraste algo.","intro":{"explanation":"Cos’è successo? es «¿qué pasó?». Para contar: ho perso (perdí), ho trovato (encontré), ho chiamato (llamé). Ojo: subito es «enseguida», no «súbitamente».","examples":[{"target":"Ho perso le chiavi di casa!","base":"¡Perdí las llaves de casa!"},{"target":"Ho chiamato subito.","base":"Llamé enseguida."}]},"takeaways":["Preguntás cos'è successo?","Contás que perdiste, encontraste o llamaste."]},{"id":"it-a2-u05-l02","unit_id":"it-a2-u05","position":2,"title_es":"Stavo leggendo","objective_es":"Decir qué estabas haciendo cuando pasó algo.","intro":{"explanation":"Para «estaba haciendo» se usa stavo + gerundio: -are → -ando (camminando), -ere / -ire → -endo (leggendo, dormendo). Mentre (mientras) va con lo que estaba pasando: mentre stavo leggendo…","examples":[{"target":"Stavo camminando in centro.","base":"Estaba caminando por el centro."},{"target":"Mentre ero in autobus, ho visto Marco.","base":"Mientras estaba en el colectivo, vi a Marco."}]},"takeaways":["Decís qué estabas haciendo: stavo + -ando / -endo.","Usás mentre para la escena."]},{"id":"it-a2-u05-rev1","unit_id":"it-a2-u05","position":3,"title_es":"Repaso 1","objective_es":"Consolidar «Cos'è successo?» y «Stavo leggendo».","intro":null,"takeaways":[]},{"id":"it-a2-u05-l03","unit_id":"it-a2-u05","position":4,"title_es":"Pioveva e all'improvviso…","objective_es":"Separar la escena (imperfetto) del hecho (passato prossimo).","intro":{"explanation":"En un relato, el imperfetto pinta la escena: pioveva, faceva freddo, c’era tanta gente. El passato prossimo cuenta lo que pasó: all’improvviso è caduto un albero. Como en español: «llovía y de repente se cayó».","examples":[{"target":"Pioveva quando sono uscita.","base":"Llovía cuando salí."},{"target":"All'improvviso è caduto un albero.","base":"De repente se cayó un árbol."}]},"takeaways":["Usás el imperfetto para la escena y el passato prossimo para el hecho.","Usás all'improvviso para el momento clave."]},{"id":"it-a2-u05-l04","unit_id":"it-a2-u05","position":5,"title_es":"Che figura!","objective_es":"Contar un momento incómodo y sus consecuencias.","intro":{"explanation":"Ojo con el falso amigo: imbarazzato es «avergonzado» o «incómodo» (embarazada se dice incinta). Quindi es «así que, por eso». Y en italiano «hacer el ridículo» es fare una brutta figura: che figura!","examples":[{"target":"Ero così imbarazzata!","base":"¡Estaba tan avergonzada!"},{"target":"Pioveva, quindi sono rimasto a casa.","base":"Llovía, así que me quedé en casa."}]},"takeaways":["Sabés que imbarazzato es «avergonzado».","Unís causa y consecuencia con quindi."]},{"id":"it-a2-u05-rev2","unit_id":"it-a2-u05","position":6,"title_es":"Repaso 2","objective_es":"Consolidar «Pioveva e all'improvviso…» y «Che figura!».","intro":null,"takeaways":[]},{"id":"it-a2-u05-l05","unit_id":"it-a2-u05","position":7,"title_es":"Raccontare un fatto","objective_es":"Contar de principio a fin algo que te pasó.","intro":{"explanation":"Un buen relato: la escena en imperfetto (pioveva, stavo leggendo), el hecho en passato prossimo (all’improvviso è successo…), y el final con un conector: per fortuna, quindi, poi.","examples":[{"target":"Mentre stavo leggendo, è arrivato Marco.","base":"Mientras estaba leyendo, llegó Marco."},{"target":"Per fortuna ho trovato le chiavi.","base":"Por suerte encontré las llaves."}]},"takeaways":["Contás un hecho con escena, momento clave y final.","Usás mentre, all’improvviso, quindi y per fortuna."]},{"id":"it-a2-u05-listen","unit_id":"it-a2-u05","position":8,"title_es":"Práctica de escucha","objective_es":"Reconocer de oído las palabras y frases de la unidad.","intro":null,"takeaways":[]},{"id":"it-a2-u05-words","unit_id":"it-a2-u05","position":9,"title_es":"Palabras de la unidad","objective_es":"Fijar el vocabulario de la unidad: reconocerlo y escribirlo.","intro":null,"takeaways":[]},{"id":"it-a2-u05-final","unit_id":"it-a2-u05","position":10,"title_es":"Repaso final","objective_es":"Demostrar todo lo de «¿Qué pasó? Contar un hecho».","intro":null,"takeaways":[]},{"id":"it-a2-u06-l01","unit_id":"it-a2-u06","position":1,"title_es":"Ti va di…?","objective_es":"Invitar a alguien y aceptar una invitación.","intro":{"explanation":"Para invitar: ti va di + infinitivo? (¿tenés ganas de…?) o che ne dici di…? (¿qué te parece…?). Para aceptar: volentieri! (¡con gusto!). Ojo: «invitar a Marco» es invitare Marco, sin a.","examples":[{"target":"Ti va di venire alla festa?","base":"¿Tenés ganas de venir a la fiesta?"},{"target":"Volentieri, grazie!","base":"¡Con gusto, gracias!"}]},"takeaways":["Invitás con ti va di…? y che ne dici di…?","Aceptás con volentieri."]},{"id":"it-a2-u06-l02","unit_id":"it-a2-u06","position":2,"title_es":"Volentieri! Mi dispiace…","objective_es":"Aceptar y rechazar con amabilidad.","intro":{"explanation":"Para aceptar: d’accordo (dale, de acuerdo). Para rechazar: mi dispiace (lo siento), non posso, devo lavorare (tengo que trabajar). Ojo: magari! es «¡ojalá!» (y magari solo, «quizás»).","examples":[{"target":"Mi dispiace, non posso: devo lavorare.","base":"Lo siento, no puedo: tengo que trabajar."},{"target":"Magari! Ma sono a Torino.","base":"¡Ojalá! Pero estoy en Turín."}]},"takeaways":["Rechazás con mi dispiace y devo…","Sabés que magari es «ojalá»."]},{"id":"it-a2-u06-rev1","unit_id":"it-a2-u06","position":3,"title_es":"Repaso 1","objective_es":"Consolidar «Ti va di…?» y «Volentieri! Mi dispiace…».","intro":null,"takeaways":[]},{"id":"it-a2-u06-l03","unit_id":"it-a2-u06","position":4,"title_es":"Sabato prossimo, tra due giorni","objective_es":"Arreglar día y hora para encontrarse.","intro":{"explanation":"Prossimo es «que viene»: sabato prossimo, la settimana prossima. Tra (o fra) + tiempo es «dentro de»: tra due giorni. Para despedirse con una cita: ci vediamo alle sette (nos vemos a las siete).","examples":[{"target":"Ci vediamo sabato prossimo.","base":"Nos vemos el sábado que viene."},{"target":"Parto tra due giorni.","base":"Me voy dentro de dos días."}]},"takeaways":["Decís sabato prossimo y tra due giorni.","Arreglás una cita con ci vediamo…"]},{"id":"it-a2-u06-l04","unit_id":"it-a2-u06","position":5,"title_es":"Andrò, farò, sarà","objective_es":"Contar planes con el futuro.","intro":{"explanation":"El futuro semplice: -are / -ere → -erò (parlerò), -ire → -irò (partirò); con noi, -emo (andremo, partiremo). Irregulares frecuentes: andrò, farò, sarò / sarà, verrò. Para planes cercanos también sirve el presente: domani vado al mare.","examples":[{"target":"L’estate prossima andrò in Puglia.","base":"El verano que viene voy a ir a Puglia."},{"target":"Sarà una bella festa.","base":"Va a ser una linda fiesta."}]},"takeaways":["Usás andrò, farò, sarà y verrò.","Contás planes de las vacaciones."]},{"id":"it-a2-u06-rev2","unit_id":"it-a2-u06","position":6,"title_es":"Repaso 2","objective_es":"Consolidar «Sabato prossimo, tra due giorni» y «Andrò, farò, sarà».","intro":null,"takeaways":[]},{"id":"it-a2-u06-l05","unit_id":"it-a2-u06","position":7,"title_es":"Un aperitivo? D'accordo!","objective_es":"Organizar una salida de principio a fin.","intro":{"explanation":"En Italia, l’aperitivo es una costumbre: después del trabajo se toma algo con picoteo antes de cenar, como nuestra previa. Para organizar: proponés (che ne dici…?), arreglás (ci vediamo alle…) y confirmás (d’accordo!).","examples":[{"target":"Che ne dici di un aperitivo?","base":"¿Qué te parece un aperitivo?"},{"target":"D'accordo, alle sette!","base":"¡Dale, a las siete!"}]},"takeaways":["Organizás una salida: proponés, arreglás y confirmás.","Conocés la costumbre del aperitivo."]},{"id":"it-a2-u06-listen","unit_id":"it-a2-u06","position":8,"title_es":"Práctica de escucha","objective_es":"Reconocer de oído las palabras y frases de la unidad.","intro":null,"takeaways":[]},{"id":"it-a2-u06-words","unit_id":"it-a2-u06","position":9,"title_es":"Palabras de la unidad","objective_es":"Fijar el vocabulario de la unidad: reconocerlo y escribirlo.","intro":null,"takeaways":[]},{"id":"it-a2-u06-final","unit_id":"it-a2-u06","position":10,"title_es":"Repaso final","objective_es":"Demostrar todo lo de «Planes e invitaciones».","intro":null,"takeaways":[]},{"id":"it-a2-u07-l01","unit_id":"it-a2-u07","position":1,"title_es":"Sto studiando","objective_es":"Decir qué estás haciendo en este momento.","intro":{"explanation":"Para «estoy haciendo» se usa stare en presente + gerundio: sto studiando, sta lavorando. Es como en español, pero se usa un poco menos: muchas veces alcanza el presente (studio all’università).","examples":[{"target":"Sto studiando per un esame.","base":"Estoy estudiando para un examen."},{"target":"Mia sorella sta lavorando.","base":"Mi hermana está trabajando."}]},"takeaways":["Decís qué estás haciendo: sto + -ando / -endo.","Hablás de la universidad y los exámenes."]},{"id":"it-a2-u07-l02","unit_id":"it-a2-u07","position":2,"title_es":"Da due anni","objective_es":"Decir desde hace cuánto hacés algo.","intro":{"explanation":"Para algo que empezó antes y sigue ahora: presente + da + tiempo. Lavoro qui da due anni = trabajo acá desde hace dos años. Ojo: con algo terminado se usa fa (sono arrivato due anni fa). Attualmente es «actualmente, en este momento».","examples":[{"target":"Studio italiano da due anni.","base":"Estudio italiano desde hace dos años."},{"target":"Attualmente lavoro in un negozio.","base":"Actualmente trabajo en una tienda."}]},"takeaways":["Decís desde cuándo: presente + da.","Distinguís da due anni de due anni fa."]},{"id":"it-a2-u07-rev1","unit_id":"it-a2-u07","position":3,"title_es":"Repaso 1","objective_es":"Consolidar «Sto studiando» y «Da due anni».","intro":null,"takeaways":[]},{"id":"it-a2-u07-l03","unit_id":"it-a2-u07","position":4,"title_es":"Il colloquio e lo stipendio","objective_es":"Entender un aviso y una entrevista de trabajo.","intro":{"explanation":"El vocabulario del trabajo: il colloquio es la entrevista (no un «coloquio»), lo stipendio es el sueldo, l’orario es el horario y il capo, el jefe o la jefa. En los avisos vas a leer cercasi (se busca).","examples":[{"target":"Domani ho un colloquio.","base":"Mañana tengo una entrevista."},{"target":"Lo stipendio è buono.","base":"El sueldo es bueno."}]},"takeaways":["Sabés que colloquio es «entrevista».","Entendés un aviso de trabajo."]},{"id":"it-a2-u07-l04","unit_id":"it-a2-u07","position":5,"title_es":"Devi, dobbiamo, può","objective_es":"Decir lo que tenés que hacer y lo que se puede.","intro":{"explanation":"Dovere (tener que): devo, devi, deve, dobbiamo, dovete, devono. Potere: posso, puoi, può, possiamo, potete, possono. Van con infinitivo: dobbiamo finire, può venire.","examples":[{"target":"Dobbiamo finire oggi.","base":"Tenemos que terminar hoy."},{"target":"Il capo può venire domani?","base":"¿El jefe puede venir mañana?"}]},"takeaways":["Conjugás dovere y potere.","Hablás de tus compañeros y tu jefe."]},{"id":"it-a2-u07-rev2","unit_id":"it-a2-u07","position":6,"title_es":"Repaso 2","objective_es":"Consolidar «Il colloquio e lo stipendio» y «Devi, dobbiamo, può».","intro":null,"takeaways":[]},{"id":"it-a2-u07-l05","unit_id":"it-a2-u07","position":7,"title_es":"Mi sono laureato","objective_es":"Hablar de tus estudios y de lo que hacés hoy.","intro":{"explanation":"La laurea es el título universitario; laurearsi es recibirse: mi sono laureato / laureata (me recibí). Para presentarte en lo profesional: mi sono laureato in…, attualmente lavoro…, da…","examples":[{"target":"Mi sono laureata due anni fa.","base":"Me recibí hace dos años."},{"target":"Ho una laurea in economia.","base":"Tengo un título en economía."}]},"takeaways":["Decís que te recibiste: mi sono laureato / laureata.","Te presentás en lo profesional."]},{"id":"it-a2-u07-listen","unit_id":"it-a2-u07","position":8,"title_es":"Práctica de escucha","objective_es":"Reconocer de oído las palabras y frases de la unidad.","intro":null,"takeaways":[]},{"id":"it-a2-u07-words","unit_id":"it-a2-u07","position":9,"title_es":"Palabras de la unidad","objective_es":"Fijar el vocabulario de la unidad: reconocerlo y escribirlo.","intro":null,"takeaways":[]},{"id":"it-a2-u07-final","unit_id":"it-a2-u07","position":10,"title_es":"Repaso final","objective_es":"Demostrar todo lo de «Trabajo y estudios».","intro":null,"takeaways":[]},{"id":"it-a2-u08-l01","unit_id":"it-a2-u08","position":1,"title_es":"Mi fa male","objective_es":"Decir qué te duele.","intro":{"explanation":"Para decir qué te duele: mi fa male + la parte del cuerpo con artículo (mi fa male la schiena) o ho mal di + la parte sin artículo (ho mal di testa, ho mal di gola).","examples":[{"target":"Mi fa male la pancia.","base":"Me duele la panza."},{"target":"Ho mal di testa da ieri.","base":"Me duele la cabeza desde ayer."}]},"takeaways":["Decís mi fa male la… y ho mal di…","Nombrás la gola, la pancia y la schiena."]},{"id":"it-a2-u08-l02","unit_id":"it-a2-u08","position":2,"title_es":"Dal medico","objective_es":"Contar tus síntomas en el consultorio.","intro":{"explanation":"Los síntomas van con avere y artículo: ho la febbre, ho la tosse, ho il raffreddore. Al médico se va con da (y no con a): vado dal medico, come vado da Marco.","examples":[{"target":"Ho la febbre e la tosse.","base":"Tengo fiebre y tos."},{"target":"Domani vado dal medico.","base":"Mañana voy al médico."}]},"takeaways":["Contás síntomas: ho la febbre, la tosse.","Decís vado dal medico."]},{"id":"it-a2-u08-rev1","unit_id":"it-a2-u08","position":3,"title_es":"Repaso 1","objective_es":"Consolidar «Mi fa male» y «Dal medico».","intro":null,"takeaways":[]},{"id":"it-a2-u08-l03","unit_id":"it-a2-u08","position":4,"title_es":"Prenda, beva","objective_es":"Entender las indicaciones del médico y de la farmacia.","intro":{"explanation":"El médico y el farmacéutico te tratan de Lei y dan indicaciones con el imperativo formal: con los verbos en -ere / -ire termina en -a (prenda, beva) y con los de -are, en -i (mangi). La ricetta es la receta del médico (y también la de cocina).","examples":[{"target":"Prenda questo sciroppo tre volte al giorno.","base":"Tome este jarabe tres veces por día."},{"target":"Ha la ricetta del medico?","base":"¿Tiene la receta del médico?"}]},"takeaways":["Entendés prenda y beva.","Pedís algo en la farmacia."]},{"id":"it-a2-u08-l04","unit_id":"it-a2-u08","position":5,"title_es":"Riposati! Non mangiare!","objective_es":"Dar consejos a un amigo con el imperativo.","intro":{"explanation":"Con tu: -are → -a (mangia), -ere / -ire → -i (prendi, bevi, dormi). En negativo: non + infinitivo (non mangiare!, non uscire!). Con un reflexivo, el pronombre va pegado al final: riposati! (descansá).","examples":[{"target":"Riposati e bevi tanto tè.","base":"Descansá y tomá mucho té."},{"target":"Non mangiare troppo!","base":"¡No comas demasiado!"}]},"takeaways":["Aconsejás con prendi, bevi, riposati.","Prohibís con non + infinitivo."]},{"id":"it-a2-u08-rev2","unit_id":"it-a2-u08","position":6,"title_es":"Repaso 2","objective_es":"Consolidar «Prenda, beva» y «Riposati! Non mangiare!».","intro":null,"takeaways":[]},{"id":"it-a2-u08-l05","unit_id":"it-a2-u08","position":7,"title_es":"Sto meglio","objective_es":"Decir que estás mejor y entender consejos para estar bien.","intro":{"explanation":"Cuando te recuperás: sto meglio (estoy mejor). Los carteles y las revistas dan consejos con el imperativo con tu: dormi, mangia, cammina, fai una pausa.","examples":[{"target":"Oggi sto meglio, grazie.","base":"Hoy estoy mejor, gracias."},{"target":"Bevi molta acqua e riposati.","base":"Tomá mucha agua y descansá."}]},"takeaways":["Decís sto meglio.","Entendés consejos de salud con el imperativo."]},{"id":"it-a2-u08-listen","unit_id":"it-a2-u08","position":8,"title_es":"Práctica de escucha","objective_es":"Reconocer de oído las palabras y frases de la unidad.","intro":null,"takeaways":[]},{"id":"it-a2-u08-words","unit_id":"it-a2-u08","position":9,"title_es":"Palabras de la unidad","objective_es":"Fijar el vocabulario de la unidad: reconocerlo y escribirlo.","intro":null,"takeaways":[]},{"id":"it-a2-u08-final","unit_id":"it-a2-u08","position":10,"title_es":"Repaso final","objective_es":"Demostrar todo lo de «Salud y bienestar».","intro":null,"takeaways":[]},{"id":"it-a2-u09-l01","unit_id":"it-a2-u09","position":1,"title_es":"Più caro, meno caro","objective_es":"Comparar con più y meno.","intro":{"explanation":"Para comparar: più (más) o meno (menos) + adjetivo + di: Roma è più grande di Firenze. Di se une al artículo: meno caro del supermercato (di + il).","examples":[{"target":"Roma è più grande di Firenze.","base":"Roma es más grande que Florencia."},{"target":"Il mercato è meno caro del supermercato.","base":"El mercado es menos caro que el súper."}]},"takeaways":["Comparás con più / meno … di.","Unís di con el artículo: del, della."]},{"id":"it-a2-u09-l02","unit_id":"it-a2-u09","position":2,"title_es":"Il migliore, bellissimo","objective_es":"Decir cuál es el mejor, el peor o el más.","intro":{"explanation":"Mejor y peor como adjetivo: migliore y peggiore (il caffè migliore della città). Para «el más»: il più / la più + adjetivo (la città più bella). Y para «muy, muy»: -issimo (bellissimo, carissimo).","examples":[{"target":"È il ristorante migliore della città.","base":"Es el mejor restaurante de la ciudad."},{"target":"La giacca è bellissima!","base":"¡La campera es hermosísima!"}]},"takeaways":["Usás migliore y peggiore.","Decís il più… y -issimo."]},{"id":"it-a2-u09-rev1","unit_id":"it-a2-u09","position":3,"title_es":"Repaso 1","objective_es":"Consolidar «Più caro, meno caro» y «Il migliore, bellissimo».","intro":null,"takeaways":[]},{"id":"it-a2-u09-l03","unit_id":"it-a2-u09","position":4,"title_es":"Posso provare?","objective_es":"Comprar ropa: talle y probador.","intro":{"explanation":"En una tienda de ropa: posso provare…? (¿puedo probarme…?), che taglia porta? (¿qué talle usa?) e il camerino (el probador). I pantaloni va en plural, como en español «los pantalones».","examples":[{"target":"Posso provare questi pantaloni?","base":"¿Puedo probarme este pantalón?"},{"target":"Il camerino è lì, a destra.","base":"El probador está ahí, a la derecha."}]},"takeaways":["Pedís probarte algo con posso provare…?","Entendés che taglia porta?"]},{"id":"it-a2-u09-l04","unit_id":"it-a2-u09","position":5,"title_es":"Sconti e saldi","objective_es":"Entender descuentos y liquidaciones.","intro":{"explanation":"Lo sconto es el descuento: lo sconto del venti per cento. I saldi son las liquidaciones de fin de temporada (en Italia, en enero y en julio). Ojo: no tienen nada que ver con el saldo de una cuenta.","examples":[{"target":"Oggi c’è lo sconto del venti per cento.","base":"Hoy hay un descuento del veinte por ciento."},{"target":"A luglio ci sono i saldi.","base":"En julio hay liquidaciones."}]},"takeaways":["Entendés lo sconto y i saldi.","Leés un cartel de liquidación."]},{"id":"it-a2-u09-rev2","unit_id":"it-a2-u09","position":6,"title_es":"Repaso 2","objective_es":"Consolidar «Posso provare?» y «Sconti e saldi».","intro":null,"takeaways":[]},{"id":"it-a2-u09-l05","unit_id":"it-a2-u09","position":7,"title_es":"Al mercato: ne prendo tre","objective_es":"Pedir cantidades en el mercado y usar ne.","intro":{"explanation":"En el mercado se pide un chilo (un kilo) o un etto (cien gramos): due etti di prosciutto. Ne reemplaza una cantidad de algo que ya se nombró: Quante mele vuole? — Ne prendo tre (llevo tres). También: Quanti anni hai? — Ne ho venti.","examples":[{"target":"Vorrei un chilo di pomodori.","base":"Quisiera un kilo de tomates."},{"target":"Quante mele vuole? — Ne prendo tre.","base":"¿Cuántas manzanas quiere? — Llevo tres."}]},"takeaways":["Pedís por chilo y por etto.","Usás ne con una cantidad."]},{"id":"it-a2-u09-listen","unit_id":"it-a2-u09","position":8,"title_es":"Práctica de escucha","objective_es":"Reconocer de oído las palabras y frases de la unidad.","intro":null,"takeaways":[]},{"id":"it-a2-u09-words","unit_id":"it-a2-u09","position":9,"title_es":"Palabras de la unidad","objective_es":"Fijar el vocabulario de la unidad: reconocerlo y escribirlo.","intro":null,"takeaways":[]},{"id":"it-a2-u09-final","unit_id":"it-a2-u09","position":10,"title_es":"Repaso final","objective_es":"Demostrar todo lo de «Compras y servicios».","intro":null,"takeaways":[]},{"id":"it-a2-u10-l01","unit_id":"it-a2-u10","position":1,"title_es":"Il cellulare","objective_es":"Nombrar el celular, la compu y la batería.","intro":{"explanation":"En Italia el celular es il cellulare (también il telefonino). La notebook es il portatile. Caricare es «cargar» (la batería) y la batteria scarica es la batería descargada.","examples":[{"target":"Il cellulare non ha batteria.","base":"El celular no tiene batería."},{"target":"Devo caricare il cellulare.","base":"Tengo que cargar el celular."}]},"takeaways":["Nombrás il cellulare, il portatile y la batteria.","Decís que tenés que cargar el celular."]},{"id":"it-a2-u10-l02","unit_id":"it-a2-u10","position":2,"title_es":"Mandare, rispondere","objective_es":"Mandar y responder mensajes y llamadas.","intro":{"explanation":"Mandare un messaggio (mandar un mensaje), rispondere (responder), una chiamata (una llamada) y una videochiamata. Scaricare es «descargar»: scaricare un’app.","examples":[{"target":"Devo mandare una mail al capo.","base":"Tengo que mandarle un mail al jefe."},{"target":"Ho fatto una videochiamata con mia nonna.","base":"Hice una videollamada con mi abuela."}]},"takeaways":["Usás mandare, rispondere y scaricare.","Hablás de llamadas y videollamadas."]},{"id":"it-a2-u10-rev1","unit_id":"it-a2-u10","position":3,"title_es":"Repaso 1","objective_es":"Consolidar «Il cellulare» y «Mandare, rispondere».","intro":null,"takeaways":[]},{"id":"it-a2-u10-l03","unit_id":"it-a2-u10","position":4,"title_es":"Ti chiamo, ti scrivo","objective_es":"Usar mi y ti para quedar en contacto.","intro":{"explanation":"Los pronombres van antes del verbo: ti chiamo (te llamo), ti scrivo (te escribo), mi mandi un messaggio? (¿me mandás un mensaje?). Ojo: ti chiamo es «te llamo», no «te llamás» (ti chiami).","examples":[{"target":"Ti chiamo stasera, va bene?","base":"Te llamo esta noche, ¿está bien?"},{"target":"Mi mandi un messaggio?","base":"¿Me mandás un mensaje?"}]},"takeaways":["Decís ti chiamo y ti scrivo.","Pedís mi mandi…?"]},{"id":"it-a2-u10-l04","unit_id":"it-a2-u10","position":5,"title_es":"Lo vedo, la chiamo","objective_es":"Reemplazar a una persona o una cosa con lo y la.","intro":{"explanation":"Para no repetir: lo (a él o algo masculino) y la (a ella o algo femenino), antes del verbo. Vedi Marco? — Sì, lo vedo. Chiami Anna? — La chiamo subito. Il portatile? Lo porto io.","examples":[{"target":"Vedi Marco oggi? — Sì, lo vedo alle cinque.","base":"¿Ves a Marco hoy? — Sí, lo veo a las cinco."},{"target":"Chiami Anna? — Sì, la chiamo subito.","base":"¿Llamás a Anna? — Sí, la llamo enseguida."}]},"takeaways":["Usás lo y la antes del verbo.","Entendés indicaciones en la oficina."]},{"id":"it-a2-u10-rev2","unit_id":"it-a2-u10","position":6,"title_es":"Repaso 2","objective_es":"Consolidar «Ti chiamo, ti scrivo» y «Lo vedo, la chiamo».","intro":null,"takeaways":[]},{"id":"it-a2-u10-l05","unit_id":"it-a2-u10","position":7,"title_es":"Gli scrivo, le telefono","objective_es":"Usar gli y le para decir a quién.","intro":{"explanation":"Para «a quién»: gli (a él) y le (a ella). Gli scrivo es «le escribo» a un hombre; le telefono, «le hablo por teléfono» a una mujer. Ojo: telefonare a va con gli / le (le telefono), pero chiamare va con lo / la (la chiamo).","examples":[{"target":"Scrivi a Marco? — Sì, gli scrivo stasera.","base":"¿Le escribís a Marco? — Sí, le escribo esta noche."},{"target":"Le telefono domani mattina.","base":"La llamo mañana a la mañana."}]},"takeaways":["Usás gli para él y le para ella.","Distinguís la chiamo de le telefono."]},{"id":"it-a2-u10-listen","unit_id":"it-a2-u10","position":8,"title_es":"Práctica de escucha","objective_es":"Reconocer de oído las palabras y frases de la unidad.","intro":null,"takeaways":[]},{"id":"it-a2-u10-words","unit_id":"it-a2-u10","position":9,"title_es":"Palabras de la unidad","objective_es":"Fijar el vocabulario de la unidad: reconocerlo y escribirlo.","intro":null,"takeaways":[]},{"id":"it-a2-u10-final","unit_id":"it-a2-u10","position":10,"title_es":"Repaso final","objective_es":"Demostrar todo lo de «Tecnología y comunicación».","intro":null,"takeaways":[]},{"id":"it-a2-u11-l01","unit_id":"it-a2-u11","position":1,"title_es":"Ti alzi, si alza","objective_es":"Conjugar los reflexivos para contar la rutina de otros.","intro":{"explanation":"Los reflexivos cambian el pronombre con cada persona: mi alzo, ti alzi, si alza, ci alziamo, vi alzate, si alzano. Igual con lavarsi y vestirsi: mi lavo, mi vesto.","examples":[{"target":"A che ora ti alzi?","base":"¿A qué hora te levantás?"},{"target":"Mio padre si alza alle sei.","base":"Mi papá se levanta a las seis."}]},"takeaways":["Conjugás los reflexivos: ti alzi, si alza, ci alziamo.","Contás la rutina de la mañana."]},{"id":"it-a2-u11-l02","unit_id":"it-a2-u11","position":2,"title_es":"Presto, tardi, spesso","objective_es":"Decir cuándo y cada cuánto hacés algo.","intro":{"explanation":"Presto es «temprano» (y a presto, «hasta pronto»); tardi, «tarde». Para la frecuencia: sempre, spesso (seguido; no «espeso»), qualche volta (a veces), non… mai (nunca): non vado mai al cinema.","examples":[{"target":"Torno a casa tardi.","base":"Vuelvo tarde a casa."},{"target":"Qualche volta vado al mare.","base":"A veces voy al mar."}]},"takeaways":["Decís presto y tardi.","Decís cada cuánto: sempre, spesso, qualche volta, mai."]},{"id":"it-a2-u11-rev1","unit_id":"it-a2-u11","position":3,"title_es":"Repaso 1","objective_es":"Consolidar «Ti alzi, si alza» y «Presto, tardi, spesso».","intro":null,"takeaways":[]},{"id":"it-a2-u11-l03","unit_id":"it-a2-u11","position":4,"title_es":"Mi sono alzata tardi","objective_es":"Contar tu mañana con los reflexivos en pasado.","intro":{"explanation":"Los reflexivos forman el pasado con essere, y el participio concuerda: mi sono alzato (él), mi sono alzata (ella), ci siamo alzati. Mi sono vestito, si è lavata…","examples":[{"target":"Stamattina mi sono alzata tardi.","base":"Esta mañana me levanté tarde."},{"target":"Ci siamo alzati alle otto.","base":"Nos levantamos a las ocho."}]},"takeaways":["Contás tu mañana: mi sono alzato / alzata.","Hacés concordar el participio."]},{"id":"it-a2-u11-l04","unit_id":"it-a2-u11","position":5,"title_es":"Ci siamo conosciuti","objective_es":"Contar cómo se conoció una pareja.","intro":{"explanation":"Con ci y si se dice lo que hacen dos personas entre sí: ci siamo conosciuti (nos conocimos), si sono sposati (se casaron). Il fidanzato / la fidanzata es el novio o la novia (también el prometido); il marito y la moglie, el marido y la esposa.","examples":[{"target":"Ci siamo conosciuti a una festa.","base":"Nos conocimos en una fiesta."},{"target":"I miei genitori si sono sposati a Roma.","base":"Mis papás se casaron en Roma."}]},"takeaways":["Contás cómo se conocieron: ci siamo conosciuti.","Nombrás fidanzato, marito y moglie."]},{"id":"it-a2-u11-rev2","unit_id":"it-a2-u11","position":6,"title_es":"Repaso 2","objective_es":"Consolidar «Mi sono alzata tardi» y «Ci siamo conosciuti».","intro":null,"takeaways":[]},{"id":"it-a2-u11-l05","unit_id":"it-a2-u11","position":7,"title_es":"Ci vado spesso","objective_es":"Usar ci para no repetir un lugar.","intro":{"explanation":"Ci reemplaza un lugar ya nombrado: Vai in palestra? — Sì, ci vado tre volte a settimana. Y con amigos: ci sentiamo (hablamos más tarde) y ci vediamo (nos vemos).","examples":[{"target":"Vai in palestra? — Sì, ci vado spesso.","base":"¿Vas al gimnasio? — Sí, voy seguido."},{"target":"Ci sentiamo stasera!","base":"¡Hablamos esta noche!"}]},"takeaways":["Usás ci en vez de repetir el lugar.","Te despedís con ci sentiamo."]},{"id":"it-a2-u11-listen","unit_id":"it-a2-u11","position":8,"title_es":"Práctica de escucha","objective_es":"Reconocer de oído las palabras y frases de la unidad.","intro":null,"takeaways":[]},{"id":"it-a2-u11-words","unit_id":"it-a2-u11","position":9,"title_es":"Palabras de la unidad","objective_es":"Fijar el vocabulario de la unidad: reconocerlo y escribirlo.","intro":null,"takeaways":[]},{"id":"it-a2-u11-final","unit_id":"it-a2-u11","position":10,"title_es":"Repaso final","objective_es":"Demostrar todo lo de «Rutina y relaciones».","intro":null,"takeaways":[]},{"id":"it-a2-u12-l01","unit_id":"it-a2-u12","position":1,"title_es":"Secondo me","objective_es":"Dar tu opinión y decir si estás de acuerdo.","intro":{"explanation":"Para opinar: secondo me (para mí), penso di sì / penso di no (creo que sí / que no). Para responder: sono d’accordo o non sono d’accordo. Invece es «en cambio».","examples":[{"target":"Non sono d'accordo con te.","base":"No estoy de acuerdo con vos."},{"target":"Secondo me è una bella idea.","base":"Para mí es una buena idea."}]},"takeaways":["Opinás con secondo me y penso di sì.","Decís sono d'accordo / non sono d'accordo."]},{"id":"it-a2-u12-l02","unit_id":"it-a2-u12","position":2,"title_es":"Mi piacerebbe, preferirei","objective_es":"Expresar deseos con el condizionale.","intro":{"explanation":"El condizionale expresa deseos de forma suave: mi piacerebbe (me gustaría), preferirei (preferiría), vorrei (quisiera), sarebbe (sería). Purtroppo (lamentablemente) es lo contrario de per fortuna.","examples":[{"target":"Mi piacerebbe vivere in Italia.","base":"Me gustaría vivir en Italia."},{"target":"Purtroppo adesso non posso.","base":"Lamentablemente ahora no puedo."}]},"takeaways":["Expresás deseos con mi piacerebbe y preferirei.","Usás purtroppo."]},{"id":"it-a2-u12-rev1","unit_id":"it-a2-u12","position":3,"title_es":"Repaso 1","objective_es":"Consolidar «Secondo me» y «Mi piacerebbe, preferirei».","intro":null,"takeaways":[]},{"id":"it-a2-u12-l03","unit_id":"it-a2-u12","position":4,"title_es":"Dovresti…","objective_es":"Dar consejos con dovresti y sarebbe meglio.","intro":{"explanation":"Para aconsejar con suavidad: dovresti + infinitivo (deberías) o sarebbe meglio + infinitivo (sería mejor). Comunque es «de todos modos, igual». Sensibile es como en español: una persona sensibile se ofende o se emociona fácil.","examples":[{"target":"Secondo me dovresti parlare con il capo.","base":"Para mí deberías hablar con el jefe."},{"target":"Comunque prova!","base":"¡Igual probá!"}]},"takeaways":["Aconsejás con dovresti y sarebbe meglio.","Usás comunque."]},{"id":"it-a2-u12-l04","unit_id":"it-a2-u12","position":5,"title_es":"Non funziona!","objective_es":"Explicar un problema con algo que compraste.","intro":{"explanation":"Para un problema: non funziona (no anda), si è rotto / si è rotta (se rompió; el participio concuerda con la cosa). Para pedir una solución: vorrei cambiare… (quisiera cambiar…).","examples":[{"target":"Il mio cellulare si è rotto.","base":"Se me rompió el celular."},{"target":"Vorrei cambiare la giacca.","base":"Quisiera cambiar la campera."}]},"takeaways":["Decís non funziona y si è rotto / rotta.","Pedís cambiar algo."]},{"id":"it-a2-u12-rev2","unit_id":"it-a2-u12","position":6,"title_es":"Repaso 2","objective_es":"Consolidar «Dovresti…» y «Non funziona!».","intro":null,"takeaways":[]},{"id":"it-a2-u12-l05","unit_id":"it-a2-u12","position":7,"title_es":"Lo scontrino e il rimborso","objective_es":"Resolver un reclamo y opinar sobre costumbres.","intro":{"explanation":"Lo scontrino es el ticket de compra (no un «descuento», que es lo sconto). Con el ticket podés pedir il rimborso (que te devuelvan la plata) o cambiare il prodotto. Para elegir con cortesía: preferirei…","examples":[{"target":"Ha lo scontrino?","base":"¿Tiene el ticket?"},{"target":"Preferirei il rimborso, grazie.","base":"Preferiría el reembolso, gracias."}]},"takeaways":["Pedís il rimborso o cambiar algo.","Distinguís lo scontrino de lo sconto."]},{"id":"it-a2-u12-listen","unit_id":"it-a2-u12","position":8,"title_es":"Práctica de escucha","objective_es":"Reconocer de oído las palabras y frases de la unidad.","intro":null,"takeaways":[]},{"id":"it-a2-u12-words","unit_id":"it-a2-u12","position":9,"title_es":"Palabra